(14,2,'{\"code\":\"AZ-TC-001\",\"title\":\"ورود موفق مدیر سیستم\",\"objective\":\"بررسی احراز هویت صحیح کاربر مدیر\",\"preconditions\":\"سامانه در حال اجرا و حساب admin فعال باشد\",\"test_data\":\"admin \\/ Pe123Ym321An\",\"expected_result\":\"ورود موفق و هدایت به داشبورد بدون خطا\",\"priority\":\"CRITICAL\",\"test_type\":\"SECURITY\",\"steps\":[{\"order\":\"1\",\"instruction\":\"باز کردن صفحهٔ ورود\",\"expected\":\"فرم ورود وسط‌چین با دو زبان نمایش یابد\"},{\"order\":\"2\",\"instruction\":\"وارد کردن admin و رمز عبور صحیح\",\"expected\":\"مقادیر پذیرفته شود\"},{\"order\":\"3\",\"instruction\":\"کلیک روی دکمهٔ ورود\",\"expected\":\"هدایت به داشبورد و نمایش منوهای چهارگانهٔ مدیر\"},{\"order\":\"4\",\"instruction\":\"بررسی سایدبار\",\"expected\":\"منوی «کارتابل من» برای مدیر وجود نداشته باشد\"}]}','ایجاد در مجموعهٔ آزمون آزمون‌یار',1,UTC_TIMESTAMP()),
(15,2,'{\"code\":\"AZ-TC-002\",\"title\":\"ورود با رمز عبور نادرست\",\"objective\":\"اطمینان از پیام خطای امن و عمومی بدون افشای جزئیات\",\"preconditions\":\"حساب admin موجود باشد\",\"test_data\":\"admin \\/ رمز غلط\",\"expected_result\":\"ورود انجام نشود و پیام امن نمایش داده شود\",\"priority\":\"CRITICAL\",\"test_type\":\"SECURITY\",\"steps\":[{\"order\":\"1\",\"instruction\":\"وارد کردن admin با رمز اشتباه\",\"expected\":\"پیام عمومی «نام کاربری یا رمز عبور نادرست است» نمایش یابد\"},{\"order\":\"2\",\"instruction\":\"بررسی پیام خطا\",\"expected\":\"پیام مشخص نکند کدام فیلد غلط است\"},{\"order\":\"3\",\"instruction\":\"باقی ماندن مقدار نام کاربری پس از خطا\",\"expected\":\"نام کاربری در فرم باقی بماند\"}]}','ایجاد در مجموعهٔ آزمون آزمون‌یار',1,UTC_TIMESTAMP()),
(16,2,'{\"code\":\"AZ-TC-003\",\"title\":\"ورود با نام کاربری ناموجود\",\"objective\":\"رفتار یکسان برای کاربر ناشناس و رمز غلط (جلوگیری از شمارش کاربران)\",\"preconditions\":null,\"test_data\":\"ghost_user \\/ هر مقدار\",\"expected_result\":\"پیام یکسان با حالت رمز غلط و عدم افشای وجود\\/عدم وجود حساب\",\"priority\":\"HIGH\",\"test_type\":\"SECURITY\",\"steps\":[{\"order\":\"1\",\"instruction\":\"وارد کردن نام کاربری ناموجود با هر رمزی\",\"expected\":\"همان پیام عمومی خطای اعتبارنامه نمایش یابد\"}]}','ایجاد در مجموعهٔ آزمون آزمون‌یار',1,UTC_TIMESTAMP()),
(17,2,'{\"code\":\"AZ-TC-004\",\"title\":\"محدودیت پنج تلاش ناموفق ورود\",\"objective\":\"جلوگیری از حملهٔ جستجوی رمز\",\"preconditions\":\"سشن جدید باز باشد\",\"test_data\":null,\"expected_result\":\"قفل موقت پس از ۵ تلاش ناموفق و باز شدن خودکار پس از مهلت\",\"priority\":\"HIGH\",\"test_type\":\"SECURITY\",\"steps\":[{\"order\":\"1\",\"instruction\":\"پنج بار ورود ناموفق پیاپی\",\"expected\":\"پس از پنجمین تلاش پیام محدودیت نمایش یابد\"},{\"order\":\"2\",\"instruction\":\"تلاش ششم حتی با رمز درست\",\"expected\":\"در بازهٔ ممنوعیت رد شود\"},{\"order\":\"3\",\"instruction\":\"صبر بیش از پنج دقیقه و تلاش مجدد با رمز درست\",\"expected\":\"ورود موفق انجام شود\"}]}','ایجاد در مجموعهٔ آزمون آزمون‌یار',1,UTC_TIMESTAMP()),
