(82,2,'{\"code\":\"AZ-TC-069\",\"title\":\"حفاظت از آخرین مدیر سیستم\",\"objective\":\"جلوگیری از قفل سیستم\",\"preconditions\":\"فقط یک مدیر فعال بماند\",\"test_data\":null,\"expected_result\":\"سیستم هرگز بدون مدیر فعال نماند\",\"priority\":\"CRITICAL\",\"test_type\":\"SECURITY\",\"steps\":[{\"order\":\"1\",\"instruction\":\"تلاش برای غیرفعال‌سازی آخرین مدیر\",\"expected\":\"رد با پیام مناسب\"},{\"order\":\"2\",\"instruction\":\"تلاش مدیر برای غیرفعال‌سازی خودش\",\"expected\":\"رد شود\"}]}','ایجاد در مجموعهٔ آزمون آزمون‌یار',1,UTC_TIMESTAMP()),
(83,2,'{\"code\":\"AZ-TC-070\",\"title\":\"زنگ اعلان‌ها با شمارندهٔ خوانده‌نشده\",\"objective\":\"آگاهی لحظه‌ای\",\"preconditions\":\"کاربری با اعلان خوانده‌نشده\",\"test_data\":null,\"expected_result\":\"چرخهٔ کامل اعلان کار کند\",\"priority\":\"MEDIUM\",\"test_type\":\"FUNCTIONAL\",\"steps\":[{\"order\":\"1\",\"instruction\":\"بررسی آیکن زنگ در نوار بالا\",\"expected\":\"شمارندهٔ خوانده‌نشده نمایش یابد\"},{\"order\":\"2\",\"instruction\":\"باز کردن زنگ\",\"expected\":\"فهرست آخرین اعلان‌ها\"},{\"order\":\"3\",\"instruction\":\"کلیک روی اعلان\",\"expected\":\"علامت خوانده‌شده و هدایت به کارتابل\"},{\"order\":\"4\",\"instruction\":\"کلیک خواندن همه\",\"expected\":\"شمارنده صفر شود\"}]}','ایجاد در مجموعهٔ آزمون آزمون‌یار',1,UTC_TIMESTAMP()),
(84,2,'{\"code\":\"AZ-TC-071\",\"title\":\"اعلان‌های کلیدی گردش کار\",\"objective\":\"رساندن درست رویداد به نفر درست\",\"preconditions\":\"سناریویی در حال اجرای کامل چرخه\",\"test_data\":null,\"expected_result\":\"هر رویداد فقط به مسئول بعدی اعلان بفرستد\",\"priority\":\"HIGH\",\"test_type\":\"FUNCTIONAL\",\"steps\":[{\"order\":\"1\",\"instruction\":\"ثبت FAIL\",\"expected\":\"فقط برنامه‌نویس اعلان خطا بگیرد\"},{\"order\":\"2\",\"instruction\":\"اعلام رفع\",\"expected\":\"فقط آزمونگر اعلان تست مجدد\"},{\"order\":\"3\",\"instruction\":\"ثبت PASS\",\"expected\":\"فقط مدیر اعلان در انتظار تأیید\"},{\"order\":\"4\",\"instruction\":\"تأیید\",\"expected\":\"فقط آزمونگر اعلان تأیید\"}]}','ایجاد در مجموعهٔ آزمون آزمون‌یار',1,UTC_TIMESTAMP()),
(85,2,'{\"code\":\"AZ-TC-072\",\"title\":\"انتخاب زبان در صفحهٔ ورود\",\"objective\":\"دوزبانگی از ابتدا\",\"preconditions\":\"صفحهٔ ورود باز باشد\",\"test_data\":null,\"expected_result\":\"زبان صفحهٔ ورود بدون ورود، قابل تغییر و حفظ شود\",\"priority\":\"HIGH\",\"test_type\":\"FUNCTIONAL\",\"steps\":[{\"order\":\"1\",\"instruction\":\"کلیک روی English در انتخابگر بالای فرم\",\"expected\":\"کل صفحهٔ ورود انگلیسی شود\"},{\"order\":\"2\",\"instruction\":\"کلیک روی فارسی\",\"expected\":\"بازگشت کامل به فارسی\"}]}','ایجاد در مجموعهٔ آزمون آزمون‌یار',1,UTC_TIMESTAMP()),
(86,2,'{\"code\":\"AZ-TC-073\",\"title\":\"تغییر زبان داخل سامانه\",\"objective\":\"دوزبانگی کامل رابط\",\"preconditions\":\"با هر نقش وارد شده باشید\",\"test_data\":null,\"expected_result\":\"کل رابط بدون رفرش دستی، بین دو زبان جابه‌جا شود\",\"priority\":\"HIGH\",\"test_type\":\"FUNCTIONAL\",\"steps\":[{\"order\":\"1\",\"instruction\":\"کلیک دکمهٔ EN در نوار بالا\",\"expected\":\"تمام منوها، برچسب‌ها و دکمه‌ها انگلیسی شوند\"},{\"order\":\"2\",\"instruction\":\"بررسی جهت صفحه\",\"expected\":\"چیدمان به LTR و سایدبار به سمت چپ منتقل شود\"},{\"order\":\"3\",\"instruction\":\"کلیک فا\",\"expected\":\"بازگشت کامل RTL فارسی\"}]}','ایجاد در مجموعهٔ آزمون آزمون‌یار',1,UTC_TIMESTAMP()),
(87,2,'{\"code\":\"AZ-TC-074\",\"title\":\"تبدیل لحظه‌ای تقویم شمسی و میلادی\",\"objective\":\"یکسان‌سازی نمایش تاریخ\",\"preconditions\":\"صفحه‌ای دارای تاریخ (داشبورد\\/کارتابل)\",\"test_data\":null,\"expected_result\":\"تاریخ‌ها با تغییر زبان بلافاصله بین شمسی و میلادی تبدیل شوند\",\"priority\":\"CRITICAL\",\"test_type\":\"FUNCTIONAL\",\"steps\":[{\"order\":\"1\",\"instruction\":\"در حالت فارسی بررسی یک تاریخ مشخص\",\"expected\":\"نمایش با تقویم جلالی (مثلاً آبان ۱۴۰۵)\"},{\"order\":\"2\",\"instruction\":\"تغییر زبان به انگلیسی\",\"expected\":\"همان لحظهٔ زمانی با تقویم میلادی (Nov 2026) نمایش یابد\"},{\"order\":\"3\",\"instruction\":\"مقایسهٔ چند نقطهٔ سیستم\",\"expected\":\"کارتابل، گرید سناریوها و تاریخچه همه یکدست باشند\"}]}','ایجاد در مجموعهٔ آزمون آزمون‌یار',1,UTC_TIMESTAMP());
